    pending: VecDeque<u32>,
    generated: usize,
    /// Tokens the client got: `generated` less the stop token and whatever
    /// a speculative round accepted past `max_tokens` or the stop.
    emitted: usize,
    max_tokens: usize,
    ignore_eos: bool,
