        let (p, b) = (&self.tray.protocol, self.layout.b as u64);
        match self.layout.run() {
            Some(_) => p.spanned(b).cloned(),
            None => p.forward(b, kern_manifest::protocol::Rows::Const(rows)).cloned(),
        }
    }

