fn ellipsize(s: &str, n: usize) -> String {
    if s.chars().count() <= n {
        s.to_string()
    } else {
        format!("{}…", s.chars().take(n - 1).collect::<String>())
    }
}

/// What was loaded, before anything runs: the sizes the manifest asked
/// for and the module every op resolved to. A run that is wrong in a
/// boring way (the wrong kernels dir, a state far bigger than expected)
/// is visible here rather than in the output.
fn banner(rt: &Runtime, manifest: &Path, kernels: Option<&Path>, load: Duration) {
    let m = &rt.manifest;
    info!("manifest `{}` (schema v{}, {}): verified", m.model, m.schema_version, manifest.display());
    for (name, v) in &m.vars {
        info!("  var      {name} ∈ [{}, {}] (caller-provided per call)", kern_manifest::types::Var::MIN, v.max);
    }
    for (name, st, alloc) in rt.state_sizes() {
        if st.bytes_per_token > 0 {
            info!(
                "  state    {name}: opaque, {} B/token × capacity {} = {}",
                st.bytes_per_token,
                rt.capacity(),
                human(alloc)
            );
        } else if st.is_per_seq() {
            info!(
                "  state    {name}: opaque, {} per sequence × {} slots = {}",
                human(st.bytes_per_seq),
                rt.seq_slots(),
                human(alloc)
            );
        } else {
            info!("  state    {name}: opaque, fixed {}", human(alloc));
        }
    }
    let mut by_kind: BTreeMap<String, (usize, u64)> = BTreeMap::new();
    for (_, kind, bytes) in rt.buffer_sizes() {
        let e = by_kind.entry(kind.to_string()).or_default();
        e.0 += 1;
        e.1 += bytes;
    }
    let kinds = ["weight", "workspace", "carry", "input", "output"]
        .iter()
        .filter_map(|c| by_kind.get(*c).map(|(n, b)| format!("{c} {n} ({})", human(*b))))
        .collect::<Vec<_>>()
        .join(" | ");
    info!("  buffers  {kinds}");
    for (name, p) in &m.programs {
        let shape = match &p.batch {
            Some(b) => format!(", {} × {:?} per call", b.groups, b.rows),
            None if p.once => ", once after load".into(),
            None => String::new(),
        };
        info!("  program  `{name}`: {} calls{shape}", p.calls.len());
    }
    info!(
        "op resolution: {} of the {} modules the manifest pins loaded from {}, entries matched by \
         cuFuncGetParamInfo layout vs declared params ({load:?}):",
        rt.module_count(),
        m.modules.len(),
        kernels.map(|k| k.display().to_string()).unwrap_or_else(|| "the registry cache".into()),
    );
    let ones = BTreeMap::from_iter(m.vars.keys().map(|v| (v.clone(), 1)));
    for (name, modules) in rt.op_resolution() {
        let op = &m.ops[&name];
        for (li, (l, module)) in op.imp.launches.iter().zip(&modules).enumerate() {
            let label = if li == 0 { name.clone() } else { format!("  ·launch{li}") };
            let sm = match l.kernel().and_then(|k| k.shared_mem.as_ref()) {
                Some(e) => format!(", shmem {:?}", e.eval(&ones).unwrap_or(0)),
                None => String::new(),
            };
            let block = l.kernel().map_or(String::new(), |k| format!(", block {:?}", k.block));
            info!(
                "  {label:<18} {:<44} {:>2} params{block}{sm} <- {module}",
                ellipsize(l.entry(), 44),
                l.params_of(op).len(),
            );
        }
    }
}

fn execute(o: Opts) -> Result<()> {
    let manifest_json = std::fs::read_to_string(&o.inputs.manifest)
        .with_context(|| format!("reading manifest {}", o.inputs.manifest.display()))?;
    let t0 = Instant::now();
    let verified = Verified::from_json(&manifest_json)?;
    // One sequence: its reach, unless told otherwise (a manifest without
    // paged state takes the runtime's fit).
    let capacity = o
        .capacity
        .or_else(|| kern_runtime::seq_capacity(&verified))
        .map(|tokens| Capacity { tokens: Some(tokens), seqs: 1 });
    let mut rt = Runtime::load(&verified, o.inputs.kernels.as_deref(), o.inputs.gpu, capacity, None)?;
    rt.set_eager(o.eager);
    banner(&rt, &o.inputs.manifest, o.inputs.kernels.as_deref(), t0.elapsed());

    let t0 = Instant::now();
    o.inputs.weights.bind(&mut rt)?;
    let n_weights = rt.buffer_sizes().iter().filter(|(_, k, _)| *k == BufferKind::Weight).count();
    info!("weights: {n_weights} buffers assembled from {} in {:?}", o.inputs.weights, t0.elapsed());

    let tokenizer = tokenizers::Tokenizer::from_file(&o.tokenizer).map_err(|e| anyhow::anyhow!("tokenizer: {e}"))?;
    info!("tokenizer {} · stop tokens {:?}", o.tokenizer.display(), o.inputs.stop_tokens);
    let prompt_ids: Vec<i64> = if o.prompt_ids.is_empty() {
        tokenizer
            .encode(o.prompt.as_str(), false)
            .map_err(|e| anyhow::anyhow!("encode: {e}"))?
            .get_ids()
            .iter()
            .map(|&u| u as i64)
            .collect()
    } else {
        o.prompt_ids.clone()
    };
    ensure!(!prompt_ids.is_empty(), "empty prompt");
    info!("prompt: {} tokens {prompt_ids:?}", prompt_ids.len());

    let mut caller = Caller::new(rt)?;
    let rows = o.rows.or_else(|| caller.protocol.row_shapes().last().copied()).unwrap_or(1);
    let step = caller.forward(Rows::Const(rows))?;
    let chunk_f = caller.chunk_forward()?;
    info!(
        "protocol: prompt through `{}` (rows as fed{}), steps through `{}` ({rows} rows{}), fills {:?}",
        chunk_f.name,
        if chunk_f.emits.is_some() { ", emits a token" } else { "" },
        step.name,
        if step.count.is_some() { ", counted" } else { "" },
        caller.protocol.fills.iter().map(|f| format!("{}={}", f.fill, f.name)).collect::<Vec<_>>()
    );
    ensure!(
        prompt_ids.len() + rows as usize <= caller.limit(),
        "prompt of {} tokens plus a {rows}-row step does not fit the sequence's {} token slots (raise --capacity)",
        prompt_ids.len(

   format!("step {k}"),
            vec![tok; rows as usize],
            1,
            keep,
            &shared,
            &fixed,
        )?;
        a.advance(1);
    }
    // What a caller would get: the outputs and the states after the workload.
    let e_last = rec.runs.last().map(|r| r.vars.clone()).unwrap_or_default();
    for (name, b) in &ma.buffers {
        if b.kind == BufferKind::Output && alike(&ma, mb, name) {
            let len = live_bytes(&ma, name, &e_last);
            rec.outputs.insert(name.clone(), (0..ranks).map(|q| a.read(q, name, len)).collect::<Result<_>>()?);
        }
    }
    for q in 0..ranks {
        let img = shared.iter().map(|n| Ok((n.clone(), a.save_state(q, n)?))).collect::<Result<_>>()?;
        rec.states.push(img);
    }
    let workload_s = t0.elapsed().as_secs_f32();

    // ---- noise floor: A's kept spans replayed from their own recording,
    // and the whole workload once more for the end-to-end band
    if o.noise {
        let t_n = Instant::now();
        let again = free_run(a, &ma, mb, &rec.runs)?;
        let rows = logit_rows(a, &ma, ranks, &rec.logits, &again)?;
        let worst = rows.iter().max_by(|x, y| x.stats.kl.total_cmp(&y.stats.kl));
        let floor = worst.map(|w| Floor {
            rows: rows.len(),
            kl_max: w.stats.kl,
            kl_at: w.label.clone(),
            flips: rows.iter().filter(|r| r.stats.flip()).count(),
        });
        let mut res: BTreeMap<String, BTreeMap<String, Vec<(String, Cmp)>>> = BTreeMap::new();
        let mut noisy_states = BTreeSet::new();
        let mut findings = Vec::new();
        let mut state_noise = Vec::new();
        let (mut compared, mut clean) = (0usize, 0usize);
        let mut cur = None;
        for &(r, s) in &rec.kept {
            let run = &rec.runs[r];
            if cur != Some(r) {
                image(a, run)?;
                cur = Some(r);
            }
            let sr = &run.spans[s];
            let rp = replay_span(a, &ma, sr, &run.program, &run.vars, false)?;
            for q in 0..ranks {
                let label = at_rank(ranks, q, &format!("{} {}", run.label, sr.span.label()));
                for (n, c) in &rp.bufs[q] {
                    compared += 1;
                    if c.identical() {
                        clean += 1;
                    } else {
                        findings.push(Finding::of_buf(&run.program, &label, n, c));
                    }
                    res.entry(run.program.clone())
                        .or_default()
                        .entry(n.clone())
                        .or_default()
                        .push((label.clone(), c.cmp.clone()));
                }
                for (name, sc) in &rp.states[q] {
                    if sc.n_diff > 0 {
                        noisy_states.insert((run.program.clone(), name.clone()));
                        state_noise.push(format!("state {name}: {} bytes at {} {label}", sc.n_diff, run.program));
                    }
                }
            }
        }
        let (shown, omitted) = cap(findings.clone(), Finding::severity);
        let report = Noise {
            compared,
            clean,
            findings: shown,
            omitted,
            states: state_noise,
            floor,
            elapsed_s: t_n.elapsed().as_secs_f32(),
        };
        rec.noise = Some(NoiseRec { report, res, noisy_states, findings });
    }

    // ---- perf: A's side of every timing
    if o.perf {
        let undriven = rec.undriven();
        let mut steps = Vec::new();
        let last_tok = *wl.decode.last().unwrap_or(&0);
        for f in &step_fs {
            let p = f.name.as_str();
            if rec.spans_of(p).is_empty() || undriven.iter().any(|u| u == p) {
                continue;
            }
            let e = a.stage(&vec![last_tok; rows_of(f) as usize])?;
            let times = a.time(p, &e, 0..a.calls(p)?, o.iters)?;
            let graph_ms = if o.graph_step { Some(a.time_graph(p, &e, 100)?) } else { None };
            steps.push(StepRec { program: p.into(), rows: rows_of(f), token: last_tok, times, graph_ms });
        }
        let mut sweep = Vec::new();
        if chunk_f.is_some() && !rec.spans_of(chunk_name).is_empty() && !undriven.iter().any(|u| u == chunk_name) {
            // The manifest's widest chunk, within what the sequence was provisioned.
            let max = pa.rows.max.min(a.provision().tokens);
            let tap_len = wl.prefill.len().min(wl.chunk) as u64;
            let mut points: BTreeSet<u64> = [tap_len].into();
            if o.sweep {
                points.extend([1u64, 16, 128, 512, 2048, 4096, max].into_iter().filter(|&t| t <= max));
            }
            let vocab = a.vocab();
            let mut rng = Rng(o.seed);
            for &t in &points {
                let tokens: Vec<i64> = (0..t).map(|_| rng.below(vocab) as i64).collect();
                a.reset();
                let e = a.stage(&tokens)?;
                let iters = if t == tap_len { o.iters } else { o.iters.min(10) };
                let times = a.time(chunk_name, &e, 0..a.calls(chunk_name)?, iters)?;
                sweep.push(SweepRec { rows: t, tokens, iters, times, tapped: t == tap_len });
            }
        }
        rec.perf = Some(PerfRec { steps, sweep });
    }
    rec.record_s = t0.elapsed().as_secs_f32();
    let image_bytes = image_bytes(&rec, a)?;
    let (snap_bytes, pieces) = rec.snapshot_bytes();
    out(&[row(
        "record",
        format!(
            "A: {} runs · {} spans kept ({} in {} pieces) · state images {} · workload {}",
            rec.runs.len(),
            rec.kept.len(),
            kb(snap_bytes),
            pieces,
            kb(image_bytes),
            crate::report::secs(workload_s)
        ),
        Some(rec.record_s),
    )]);
    Ok(rec)
}

